import os, re
root=r'C:\Users\12159\AppData\Local\Temp\ai_exec_benchmark\trial_ai_exec_02'
for fn in ['Makefile','CMakeLists.txt','test/CMakeLists.txt','readme.md']:
    p=os.path.join(root,*fn.split('/'))
    print('\n===== '+fn+' =====')
    with open(p,'r',encoding='utf-8',errors='replace') as f: txt=f.read()
    if fn=='readme.md':
        # Print only build/test-related lines with context
        lines=txt.splitlines()
        hits=[]
        for i,l in enumerate(lines):
            if re.search(r'build|test|make|cmake|compile|windows|mingw',l,re.I):
                hits.extend(range(max(0,i-2),min(len(lines),i+4)))
        for i in sorted(set(hits)):
            print(f'{i+1:4}: {lines[i]}')
    else:
        print(txt[:20000])
print('\nTest tree (files):')
for dp,ds,fs in os.walk(os.path.join(root,'test')):
    for f in fs:
        print(os.path.relpath(os.path.join(dp,f),root))
